        max={max}
        value={value}
        onChange={(event) => onChange(event.target.value)}
        placeholder="—"
        className="h-7 w-16 min-w-0 bg-background border-border px-1.5 text-xs text-foreground focus:border-[color:var(--clr-accent-hi)]"
      />
