    const meters: MeterReportGroup[] = [
      makeMeter({ deviceId: "d1", deviceSerialNo: "DEV-A1", meterSerialNo: "M-A1",
        readings: [makeReading({ id: "r1", deviceId: "d1", customerName: "CUST A" })] }),
